    if(([string]$Envelope.remote_commit_sha).Trim().ToLowerInvariant()-notmatch'^[0-9a-f]{40}$' -or -not(Test-CustomAppProductionDurableDualTransactionIdBridgeIntegrationNonceV010([string]$Envelope.transaction_nonce))){return [pscustomobject]@{ok=$false;reason='durable-dual-id-precommit-remote-or-nonce-invalid'}}
