    try{if([int]$Envelope.app_backup_file_count-lt1 -or [int64]$Envelope.app_backup_total_bytes-lt1){return [pscustomobject]@{ok=$false;reason='durable-dual-id-precommit-backup-count-invalid'}}}catch{return [pscustomobject]@{ok=$false;reason='durable-dual-id-precommit-backup-count-invalid'}}
    foreach($f in @('transaction_root','live_path','stage_workspace_path','stage_path','app_backup_path','persistence_backup_path')){try{[void](Assert-CustomAppProductionCrashJournalPathV010 -AllowedRoot $AllowedRoot -Path ([string]$Envelope.$f) -Label ('durable dual id '+$f))}catch{return [pscustomobject]@{ok=$false;reason=('durable-dual-id-precommit-path-invalid-'+$f+':'+[string]$_.Exception.Message)}}}
    $live=[IO.Path]::GetFullPath([string]$Envelope.live_path).TrimEnd([IO.Path]::DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar);$txn=[IO.Path]::GetFullPath([string]$Envelope.transaction_root).TrimEnd([IO.Path]::DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar)
    if(-not([IO.Path]::GetDirectoryName($txn)).Equals([IO.Path]::GetDirectoryName($live),[StringComparison]::OrdinalIgnoreCase) -or [IO.Path]::GetFileName($txn)-notmatch'^\.spotify-control-txn-[0-9a-f]{32}$'){return [pscustomobject]@{ok=$false;reason='durable-dual-id-precommit-transaction-root-invalid'}}
    $p=[DateTimeOffset]::MinValue;$q=[DateTimeOffset]::MinValue;if(-not[DateTimeOffset]::TryParse([string]$Envelope.prepared_at,[ref]$p)-or-not[DateTimeOffset]::TryParse([string]$Envelope.post_backup_revalidated_at,[ref]$q)-or$q-lt$p){return [pscustomobject]@{ok=$false;reason='durable-dual-id-precommit-time-invalid'}}
    if(-not[bool]$Envelope.append_only){return [pscustomobject]@{ok=$false;reason='durable-dual-id-precommit-not-append-only'}}
