function New-CustomAppProductionDurableDualTransactionIdBridgeIntegrationPrecommitV010 {
    param(
        [Parameter(Mandatory=$true)]$RecoveryAwarePreparedResult,[Parameter(Mandatory=$true)]$RecoveryAwareStageExecutorResult,
        [Parameter(Mandatory=$true)][string]$Name,[Parameter(Mandatory=$true)][string]$AllowedRoot,[Parameter(Mandatory=$true)][string]$LivePath,[Parameter(Mandatory=$true)][string]$TransactionNonce
    )
    $pc=Test-CustomAppProductionRecoveryAwarePermitPreApplyPreparedResultV010 -Result $RecoveryAwarePreparedResult;if($null-eq$pc-or-not[bool]$pc.ok){throw ('durable-dual-id-recovery-prepared-invalid:'+[string]$pc.reason)}
    $sc=Test-CustomAppProductionRecoveryAwarePermitStageExecutorResultV010 -Result $RecoveryAwareStageExecutorResult;if($null-eq$sc-or-not[bool]$sc.ok){throw ('durable-dual-id-recovery-stage-invalid:'+[string]$sc.reason)}
    $nameKey=$Name.Trim().ToLowerInvariant();if([string]::IsNullOrWhiteSpace($nameKey)-or([string]$RecoveryAwarePreparedResult.name).Trim().ToLowerInvariant()-cne$nameKey){throw 'durable-dual-id-name-mismatch'}
    $permitId=([string]$RecoveryAwarePreparedResult.transaction_id).Trim().ToLowerInvariant();if(-not(Test-CustomAppProductionDurableDualTransactionIdBridgeIntegrationSha256V010 $permitId)){throw 'durable-dual-id-permit-transaction-invalid'}
    if(([string]$RecoveryAwareStageExecutorResult.transaction_id).Trim().ToLowerInvariant()-cne$permitId){throw 'durable-dual-id-stage-transaction-mismatch'}
    if(([string]$RecoveryAwarePreparedResult.recovery_stage_result_fingerprint).Trim().ToLowerInvariant()-cne([string]$RecoveryAwareStageExecutorResult.result_fingerprint).Trim().ToLowerInvariant()){throw 'durable-dual-id-stage-fingerprint-mismatch'}
    if(-not(Test-CustomAppProductionDurableDualTransactionIdBridgeIntegrationNonceV010 $TransactionNonce)){throw 'durable-dual-id-transaction-nonce-invalid'}
    $g=ConvertTo-CustomAppProductionRecoveryAwarePermitGenericPreparedResultV010 -Result $RecoveryAwarePreparedResult;$gc=Test-CustomAppProductionPreApplyPreparedResultV010 -Result $g;if($null-eq$gc-or-not[bool]$gc.ok){throw ('durable-dual-id-generic-prepared-invalid:'+[string]$gc.reason)}
    $txn=Get-CustomAppProductionJournalAwareAtomicTransactionRootV010 -LivePath $LivePath -TransactionNonce $TransactionNonce
    $identity=New-CustomAppProductionCrashJournalIdentityV010 -Name $Name -ConsumptionId ([string]$g.consumption_id) -SourceIdentity ([string]$g.source_identity) -RemoteCommitSha ([string]$g.remote_commit_sha) -StageResultFingerprint ([string]$g.stage_result_fingerprint) -PreparationFingerprint ([string]$g.preparation_fingerprint) -AllowedRoot $AllowedRoot -LivePath $LivePath -TransactionRoot $txn -StageWorkspacePath ([string]$g.stage_workspace_path) -AppBackupPath ([string]$g.app_backup_path) -PersistenceBackupPath ([string]$g.persistence_backup_path)
    $journalId=([string]$identity.transaction_id).Trim().ToLowerInvariant();if($journalId-ceq$permitId){throw 'durable-dual-id-transaction-namespaces-conflated'}
