        qualified_bridge_head=$CustomAppProductionDurableDualTransactionIdBridgeIntegrationQualifiedBridgeHead;qualified_bridge_core_blob=$CustomAppProductionDurableDualTransactionIdBridgeIntegrationQualifiedBridgeCoreBlob
        qualified_recovery_aware_prepared_head=$CustomAppProductionDurableDualTransactionIdBridgeIntegrationQualifiedPreparedHead;qualified_recovery_aware_prepared_core_blob=$CustomAppProductionDurableDualTransactionIdBridgeIntegrationQualifiedPreparedCoreBlob
        qualified_evidence_bound_atomic_head=$CustomAppProductionDurableDualTransactionIdBridgeIntegrationQualifiedAtomicHead;qualified_evidence_bound_atomic_core_blob=$CustomAppProductionDurableDualTransactionIdBridgeIntegrationQualifiedAtomicCoreBlob;qualified_crash_journal_head=$CustomAppProductionDurableDualTransactionIdBridgeIntegrationQualifiedJournalHead
        status='dual-transaction-id-bridge-precommitted-before-journal-init';name=$nameKey;source_identity=([string]$g.source_identity).Trim().ToLowerInvariant();remote_commit_sha=([string]$g.remote_commit_sha).Trim().ToLowerInvariant();consumption_id=([string]$g.consumption_id).Trim().ToLowerInvariant()
        permit_transaction_id=$permitId;expected_journal_transaction_id=$journalId;transaction_id_namespaces_distinct=$true;transaction_nonce=$TransactionNonce.Trim().ToLowerInvariant();transaction_root=[string]$identity.transaction_root
        recovery_pre_apply_result_fingerprint=([string]$RecoveryAwarePreparedResult.result_fingerprint).Trim().ToLowerInvariant();recovery_stage_result_fingerprint=([string]$RecoveryAwareStageExecutorResult.result_fingerprint).Trim().ToLowerInvariant();generic_stage_result_fingerprint=([string]$RecoveryAwarePreparedResult.generic_stage_result_fingerprint).Trim().ToLowerInvariant();generic_preparation_fingerprint=([string]$g.preparation_fingerprint).Trim().ToLowerInvariant()
        live_path=[string]$identity.live_path;stage_workspace_path=[string]$identity.stage_workspace_path;stage_path=[string]$g.stage_path;app_backup_path=[string]$identity.app_backup_path;app_backup_tree_sha256=([string]$g.app_backup_tree_sha256).Trim().ToLowerInvariant();app_backup_file_count=[int]$g.app_backup_file_count;app_backup_total_bytes=[int64]$g.app_backup_total_bytes;persistence_backup_path=[string]$identity.persistence_backup_path;persistence_fingerprint=([string]$g.persistence_fingerprint).Trim().ToLowerInvariant()
        prepared_at=[string]$RecoveryAwarePreparedResult.prepared_at;post_backup_revalidated_at=[string]$RecoveryAwarePreparedResult.post_backup_revalidated_at
        append_only=$true;precommit_is_authority=$false;execution_authorized=$false;finalization_authorized=$false;spicetify_apply_authorized=$false;cleanup_authorized=$false;production_mutation_authorized=$false;precommit_fingerprint=$null
    }
    $e.precommit_fingerprint=Get-CustomAppProductionDurableDualTransactionIdBridgeIntegrationSha256V010 (Get-CustomAppProductionDurableDualTransactionIdBridgeIntegrationPrecommitMaterialV010 -Envelope $e)
