function Read-CustomAppProductionDurableDualTransactionIdBridgeIntegrationPrecommitUnlockedV010 {
    param([Parameter(Mandatory=$true)][string]$AllowedRoot,[Parameter(Mandatory=$true)][string]$Path)
    if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){return [pscustomobject]@{ok=$false;reason='durable-dual-id-precommit-not-found';precommit=$null}}
    $item=Get-Item -LiteralPath $Path -Force -ErrorAction Stop;if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){throw 'durable-dual-id-precommit-reparse-point'};if($item.Length-gt1048576){throw 'durable-dual-id-precommit-exceeds-1MiB'}
    $raw=[IO.File]::ReadAllText($Path,(New-Object Text.UTF8Encoding($false)));try{$e=$raw|ConvertFrom-Json}catch{throw 'durable-dual-id-precommit-json-invalid'}
    $c=Test-CustomAppProductionDurableDualTransactionIdBridgeIntegrationPrecommitV010 -Envelope $e -AllowedRoot $AllowedRoot;if(-not[bool]$c.ok){throw ('durable-dual-id-precommit-invalid:'+[string]$c.reason)}
    return [pscustomobject]@{ok=$true;reason='durable-dual-id-precommit-read-valid';precommit=$e;precommit_fingerprint=[string]$c.precommit_fingerprint;path=$Path}
}
function Read-CustomAppProductionDurableDualTransactionIdBridgeIntegrationPrecommitV010 {
    param([Parameter(Mandatory=$true)][string]$AllowedRoot,[Parameter(Mandatory=$true)][string]$JournalStoreDirectory)
    try{$jp=Get-CustomAppProductionCrashJournalPathsV010 -AllowedRoot $AllowedRoot -StoreDirectory $JournalStoreDirectory}catch{return [pscustomobject]@{ok=$false;reason=('durable-dual-id-precommit-store-denied:'+[string]$_.Exception.Message);precommit=$null}}
    $paths=Get-CustomAppProductionDurableDualTransactionIdBridgeIntegrationPathsV010 $jp;$lock=$null
    try{$lock=Open-CustomAppProductionCrashJournalLockV010 $jp;return Read-CustomAppProductionDurableDualTransactionIdBridgeIntegrationPrecommitUnlockedV010 -AllowedRoot ([string]$jp.allowed_root) -Path ([string]$paths.precommit)}catch{return [pscustomobject]@{ok=$false;reason=('durable-dual-id-precommit-read-denied:'+[string]$_.Exception.Message);precommit=$null}}finally{if($null-ne$lock){$lock.Dispose()}}
}
function Write-CustomAppProductionDurableDualTransactionIdBridgeIntegrationPrecommitV010 {
    param([Parameter(Mandatory=$true)][string]$AllowedRoot,[Parameter(Mandatory=$true)][string]$JournalStoreDirectory,[Parameter(Mandatory=$true)]$Precommit)
    $deny={param([string]$Reason)[pscustomobject]@{ok=$false;reason=$Reason;persisted=$false;replayed=$false;precommit=$null;precommit_is_authority=$false;production_mutation_authorized=$false}}
    $check=Test-CustomAppProductionDurableDualTransactionIdBridgeIntegrationPrecommitV010 -Envelope $Precommit -AllowedRoot $AllowedRoot;if(-not[bool]$check.ok){return & $deny ('durable-dual-id-precommit-envelope-denied:'+[string]$check.reason)}
    try{$jp=Get-CustomAppProductionCrashJournalPathsV010 -AllowedRoot $AllowedRoot -StoreDirectory $JournalStoreDirectory -Create:$true}catch{return & $deny ('durable-dual-id-precommit-store-create-denied:'+[string]$_.Exception.Message)};$paths=Get-CustomAppProductionDurableDualTransactionIdBridgeIntegrationPathsV010 $jp;$lock=$null
