        if([bool]$journal.ok){return & $deny 'durable-dual-id-precommit-journal-already-initialized-recovery-required'};if([string]$journal.reason-cne'journal-uninitialized'){return & $deny ('durable-dual-id-precommit-journal-state-invalid:'+[string]$journal.reason)}
        if(Test-Path -LiteralPath ([string]$paths.receipt)){return & $deny 'durable-dual-id-precommit-final-receipt-exists-before-journal'}
        if(Test-Path -LiteralPath ([string]$paths.precommit)){
            $old=Read-CustomAppProductionDurableDualTransactionIdBridgeIntegrationPrecommitUnlockedV010 -AllowedRoot ([string]$jp.allowed_root) -Path ([string]$paths.precommit)
            if(-not[bool]$old.ok){return & $deny ([string]$old.reason)};if(([string]$old.precommit_fingerprint).Trim().ToLowerInvariant()-cne([string]$Precommit.precommit_fingerprint).Trim().ToLowerInvariant()){return & $deny 'durable-dual-id-precommit-existing-binding-mismatch'}
            return [pscustomobject]@{ok=$true;reason='durable-dual-id-precommit-existing-exact-replay';persisted=$true;replayed=$true;precommit=$old.precommit;precommit_fingerprint=[string]$old.precommit_fingerprint;path=[string]$paths.precommit;precommit_is_authority=$false;production_mutation_authorized=$false}
        }
        $json=$Precommit|ConvertTo-Json -Depth 40 -Compress;Write-CustomAppProductionCrashJournalDurableFileV010 -Path ([string]$paths.precommit) -Text $json -Mode ([IO.FileMode]::CreateNew)
        $verify=Read-CustomAppProductionDurableDualTransactionIdBridgeIntegrationPrecommitUnlockedV010 -AllowedRoot ([string]$jp.allowed_root) -Path ([string]$paths.precommit);if(-not[bool]$verify.ok -or ([string]$verify.precommit_fingerprint).Trim().ToLowerInvariant()-cne([string]$Precommit.precommit_fingerprint).Trim().ToLowerInvariant()){throw 'durable-dual-id-precommit-readback-mismatch'}
        return [pscustomobject]@{ok=$true;reason='durable-dual-id-precommit-created-readback-verified';persisted=$true;replayed=$false;precommit=$verify.precommit;precommit_fingerprint=[string]$verify.precommit_fingerprint;path=[string]$paths.precommit;precommit_is_authority=$false;production_mutation_authorized=$false}
    }catch{return & $deny ('durable-dual-id-precommit-write-failed:'+[string]$_.Exception.Message)}finally{if($null-ne$lock){$lock.Dispose()}}
}
