function Write-CustomAppProductionDurableDualTransactionIdBridgeIntegrationReceiptV010 {
    param([Parameter(Mandatory=$true)][string]$AllowedRoot,[Parameter(Mandatory=$true)][string]$JournalStoreDirectory,[Parameter(Mandatory=$true)]$Receipt)
    $deny={param([string]$Reason)[pscustomobject]@{ok=$false;reason=$Reason;persisted=$false;replayed=$false;receipt=$null;bridge_is_authority=$false;production_mutation_authorized=$false}}
    try{$jp=Get-CustomAppProductionCrashJournalPathsV010 -AllowedRoot $AllowedRoot -StoreDirectory $JournalStoreDirectory}catch{return & $deny ('durable-dual-id-final-store-denied:'+[string]$_.Exception.Message)};$paths=Get-CustomAppProductionDurableDualTransactionIdBridgeIntegrationPathsV010 $jp;$lock=$null
    try{
        $lock=Open-CustomAppProductionCrashJournalLockV010 $jp;$pre=Read-CustomAppProductionDurableDualTransactionIdBridgeIntegrationPrecommitUnlockedV010 -AllowedRoot ([string]$jp.allowed_root) -Path ([string]$paths.precommit);if(-not[bool]$pre.ok){return & $deny ([string]$pre.reason)}
