        if(Test-Path -LiteralPath ([string]$paths.receipt)){$old=Read-CustomAppProductionDurableDualTransactionIdBridgeIntegrationReceiptUnlockedV010 -AllowedRoot ([string]$jp.allowed_root) -Path ([string]$paths.receipt) -Precommit $pre.precommit;if(-not[bool]$old.ok){return & $deny ([string]$old.reason)};if(([string]$old.bridge_fingerprint).Trim().ToLowerInvariant()-cne([string]$Receipt.bridge_fingerprint).Trim().ToLowerInvariant()){return & $deny 'durable-dual-id-final-existing-receipt-mismatch'};return [pscustomobject]@{ok=$true;reason='durable-dual-id-final-receipt-existing-exact-replay';persisted=$true;replayed=$true;receipt=$old.receipt;bridge_fingerprint=[string]$old.bridge_fingerprint;path=[string]$paths.receipt;bridge_is_authority=$false;production_mutation_authorized=$false}}
